CREATE TABLE public.scrim_transaction_log (id uuid DEFAULT gen_random_uuid() NOT NULL, scrim_id uuid NOT NULL, event_type text NOT NULL, timestamp timetz DEFAULT now() NOT NULL, acting_player_id uuid NOT NULL, team_name text NOT NULL, player_one_id uuid, player_two_id uuid, player_three_id uuid, old_player_id uuid, new_player_id uuid, old_team_name text, PRIMARY KEY (id), FOREIGN KEY (scrim_id) REFERENCES public.scrims (id) ON UPDATE RESTRICT ON DELETE RESTRICT, FOREIGN KEY (acting_player_id) REFERENCES public.players (id) ON UPDATE RESTRICT ON DELETE RESTRICT, FOREIGN KEY (player_one_id) REFERENCES public.players (id) ON UPDATE RESTRICT ON DELETE RESTRICT, FOREIGN KEY (player_two_id) REFERENCES public.players (id) ON UPDATE RESTRICT ON DELETE RESTRICT, FOREIGN KEY (player_three_id) REFERENCES public.players (id) ON UPDATE RESTRICT ON DELETE RESTRICT, FOREIGN KEY (old_player_id) REFERENCES public.players (id) ON UPDATE RESTRICT ON DELETE RESTRICT, FOREIGN KEY (new_player_id) REFERENCES public.players (id) ON UPDATE RESTRICT ON DELETE RESTRICT);
